"""Original hepatic vascular disorders chapter."""
from qbank_authoring import question,ref,finalize
VA=ref('EASL 2025 Vascular Diseases of the Liver Guideline','https://doi.org/10.1016/j.jhep.2025.08.001')
PV=ref('AGA Portal Vein Thrombosis in Cirrhosis Clinical Practice Update','https://doi.org/10.1053/j.gastro.2024.10.038')
BV=ref('Baveno VIII 2026 Portal Hypertension Consensus','https://www.journal-of-hepatology.eu/article/S0168-8278%2826%2902778-9/fulltext')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('A young adult develops painful hepatomegaly and ascites. Doppler shows absent hepatic vein flow with venous collaterals. Which diagnosis is favored?', 'Budd–Chiari syndrome',[
 ('Isolated extrahepatic portal vein thrombosis','This obstructs portal inflow rather than hepatic venous outflow.'),('Primary biliary cholangitis','This is a small-duct cholangiopathy, not the stated vascular lesion.'),('Gilbert syndrome','This does not cause ascites or absent hepatic venous flow.')],
 'Localize the obstruction before naming the disease', '**Budd–Chiari is hepatic venous outflow obstruction, apart from cardiac/pericardial causes and sinusoidal obstruction syndrome.**', ['The presentation ranges from acute failure to chronic portal hypertension.','Doppler is a useful initial test, with CT/MRI for confirmation and anatomy.'], '**Search for a prothrombotic cause.**', ['Myeloproliferative disease and other acquired/inherited risks are relevant.','Normal peripheral counts do not eliminate an occult hematological disorder.'], [['Budd–Chiari','Hepatic venous outflow'],['PVT','Portal inflow'],['Cardiac congestion','Separate downstream cause']], [VA], 'clinical_scenario')
q('What is a suitable initial vascular imaging test for suspected Budd–Chiari syndrome?', 'Expert Doppler ultrasonography',[
 ('A plain radiograph as definitive vascular mapping','It cannot characterize venous flow adequately.'),('ERCP as the standard venous test','ERCP evaluates bile ducts, not hepatic venous patency.'),('A serum bilirubin fraction alone','This does not show the obstructed vessel.')],
 'Assess both vessel anatomy and flow', '**Doppler can identify obstruction, abnormal flow and collaterals.**', ['Contrast CT or MRI can define extent and procedural anatomy.','A technically limited negative examination does not settle a high-suspicion case.'], '**Select further tests for the unresolved question.**', ['Venography is used in selected diagnostic/interventional settings.','Biopsy is useful when small-vein disease or another process remains uncertain.'], [['Doppler','Initial flow assessment'],['CT/MRI','Extent and anatomy'],['Selected invasive test','Specific unresolved question']], [VA])
q('Why is JAK2 V617F testing relevant in otherwise unexplained Budd–Chiari syndrome?', 'It can identify an occult myeloproliferative neoplasm even when peripheral blood counts are not elevated',[
 ('It is the gene responsible for every case of Wilson disease','Wilson disease involves ATP7B.'),('A normal blood count makes the test universally unnecessary','Hypersplenism, dilution and iron status can mask the phenotype.'),('It diagnoses all inherited thrombophilias','It assesses a specific acquired clonal mechanism, not every thrombophilia.')],
 'Splanchnic thrombosis can precede an obvious hematological phenotype', '**Myeloproliferative neoplasms are important causes of hepatic/splanchnic venous thrombosis.**', ['The work-up may include other clonal and thrombotic conditions.','Several risk factors can coexist.'], '**Coordinate hematology and hepatology care.**', ['Treating the clot alone may leave the underlying disorder unaddressed.','A negative JAK2 test does not end every hematological investigation.'], [['JAK2','Clonal myeloproliferative clue'],['Normal counts','Does not exclude'],['Care','Underlying cause plus vascular disease']], [VA])
q('After primary Budd–Chiari syndrome is established, what is a usual foundational treatment?', 'Anticoagulation unless a specific contraindication requires an alternative plan',[
 ('Routine absence of anticoagulation because portal varices always prohibit it','Varices require prevention/management but are not a universal absolute ban.'),('UDCA alone as definitive treatment of the venous obstruction','It does not restore venous patency.'),('Corticosteroids as universal clot-dissolving therapy','They are not standard treatment of primary thrombotic outflow obstruction.')],
 'Prevent progression while deciding whether decompression is needed', '**Anticoagulation and treatment of the prothrombotic condition are core elements.**', ['Agent selection accounts for liver function, bleeding risk and the underlying thrombophilia.','Many patients require long-term treatment.'], '**Escalate according to response and anatomy.**', ['A short stenosis may be amenable to angioplasty/stenting.','Persistent disease can require TIPS or transplantation.'], [['Foundation','Anticoagulation/cause treatment'],['Focal lesion','Recanalization option'],['Persistent failure','Decompression or transplant']], [VA])
q('A Budd–Chiari patient has a short accessible hepatic venous stenosis and persistent symptoms despite medical care. Which intervention is anatomically attractive?', 'Balloon angioplasty with or without stenting',[
 ('Immediate total hepatectomy without reconstruction or transplant','This is not a viable standard intervention.'),('Endoscopic bile-duct sphincterotomy','It does not address the venous lesion.'),('Splenic artery embolization as an equivalent direct repair','It does not recanalize the hepatic venous stenosis.')],
 'A focal correctable lesion can permit physiological outflow restoration', '**Short stenoses may be treated by endovascular recanalization.**', ['Technical feasibility and remaining hepatic reserve matter.','Continue management of the thrombotic cause.'], '**Assess response before assuming every case needs a shunt.**', ['Persistent or unsuitable obstruction may require TIPS.','Advanced failure can lead directly to transplant consideration.'], [['Short stenosis','Angioplasty/stent'],['Persistent diffuse obstruction','TIPS assessment'],['Failure beyond rescue','Transplant assessment']], [VA], 'clinical_scenario')
q('Budd–Chiari causes refractory ascites and hepatic dysfunction despite anticoagulation, and simple venous recanalization is not feasible. What is a standard next decompressive consideration?', 'TIPS at an experienced center',[
 ('Repeated antibiotic courses without an infection indication','This does not decompress the venous system.'),('ERCP with a plastic biliary stent','The obstruction is vascular, not biliary.'),('No escalation until every hepatic function is lost','Delayed escalation can worsen outcome.')],
 'Create an alternative outflow pathway when native repair is unsuitable', '**TIPS is a major component of the stepwise Budd–Chiari strategy.**', ['Complex anatomy can require specialist techniques.','Cardiac and hepatic suitability must be assessed.'], '**Maintain a transplant pathway when decompression is insufficient.**', ['Acute severe failure may need expedited decisions.','Clinical response determines the pace of escalation.'], [['Medical therapy inadequate','Interventional review'],['TIPS','Alternative decompression'],['Persistent severe failure','Transplant']], [VA], 'clinical_scenario')
q('A Budd–Chiari patient has rapidly progressive liver failure despite appropriate treatment. What is the definitive escalation to assess?', 'Liver transplantation',[
 ('A requirement to repeat unsuccessful angioplasty indefinitely','Repeated futile procedures can delay definitive care.'),('Stopping anticoagulation as the only response','This does not reverse established failure.'),('Oral diuretics alone regardless of shock and encephalopathy','Supportive treatment alone may be insufficient.')],
 'A step-up strategy must include a timely endpoint', '**Transplant can be necessary when liver failure is not recoverable with outflow treatment.**', ['Selection considers the cause, organ dysfunction and overall prognosis.','The prothrombotic disorder still needs long-term planning.'], '**Refer before the patient becomes unsalvageable.**', ['In some acute severe cases, prolonged sequential attempts are inappropriate.','Expert-center discussion individualizes the sequence.'], [['Reversible obstruction','Restore/decompress'],['Irreversible severe failure','Transplant assessment'],['Underlying thrombophilia','Continued management']], [VA], 'clinical_scenario')
q('A noncirrhotic patient has recent portal vein thrombosis and severe abdominal pain with mesenteric extension. What is the principal immediate concern?', 'Intestinal ischemia requiring urgent multidisciplinary assessment and anticoagulation when appropriate',[
 ('Only a future cosmetic splenomegaly issue','Mesenteric involvement can threaten bowel viability now.'),('A mandatory diagnosis of cirrhosis','PVT can occur without cirrhosis.'),('A reason to delay all care until cavernous transformation forms','Delay can permit progression and infarction.')],
 'Extension changes the urgency', '**Portal-mesenteric thrombosis can compromise intestinal venous drainage.**', ['Assess peritonism, lactate, organ dysfunction and contrast imaging findings.','A normal early lactate does not guarantee viable bowel.'], '**Treat the clot and the bowel threat together.**', ['Anticoagulation is important unless contraindicated.','Peritonitis or infarction can require surgery and additional intervention.'], [['Isolated stable PVT','Vascular treatment pathway'],['Mesenteric extension/pain','Ischemia assessment'],['Peritonitis','Urgent surgical concern']], [VA], 'clinical_scenario')
q('Why is contrast CT or MRI often obtained after Doppler identifies PVT?', 'Confirm extent, chronicity clues, mesenteric involvement and possible malignant thrombus',[
 ('A Doppler result always proves tumor invasion','Bland and malignant thrombi require differentiation.'),('Cross-sectional imaging has no role once any flow defect is seen','Extent and cause can change management.'),('To replace all clinical assessment of bowel ischemia','Imaging and clinical findings must be integrated.')],
 'The label PVT is only the beginning of treatment planning', '**Location and degree of occlusion affect the recanalization strategy.**', ['Assess whether the main trunk, branches and mesenteric veins are involved.','Look for an adjacent tumor and enhancement characteristics.'], '**Preserve an accurate baseline for follow-up.**', ['Serial imaging can show progression or recanalization.','Transplant feasibility can depend on the anatomy.'], [['Extent','Treatment and ischemia relevance'],['Cause','Bland versus tumor'],['Follow-up','Objective change']], [VA,PV])
q('Which imaging feature favors portal vein tumor thrombus over bland PVT in a patient with HCC?', 'Enhancing soft tissue within the expanded vein contiguous with tumor',[
 ('A nonenhancing filling defect alone','This can represent bland thrombus.'),('Cavernous collaterals alone','These indicate chronic obstruction, not necessarily malignancy.'),('A low platelet count alone','This is nonspecific and does not identify tumor invasion.')],
 'Tumor invasion and thrombosis have different oncological implications', '**Internal enhancement and continuity with a tumor are concerning for malignant invasion.**', ['Doppler arterial signals can provide additional clues.','Equivocal findings may need expert multimodal review.'], '**Do not use anticoagulation as a substitute for cancer staging.**', ['A bland component can coexist.','Treatment depends on the cancer and vascular assessment together.'], [['Tumor thrombus','Enhancing tissue/invasion'],['Bland thrombus','Usually nonenhancing clot'],['Consequence','Changes staging and management']], [VA,PV])
q('Under the AGA PVT-in-cirrhosis update, what is a reasonable approach to a recent 30% main portal vein occlusion without ischemia or progression?', 'Selected observation with repeat imaging about every three months, after individual risk assessment',[
 ('Immediate mandatory surgery in every such case','The limited stable phenotype can be observed selectively.'),('Never repeat imaging because the degree cannot change','Progression can alter the treatment indication.'),('Apply the same rule regardless of transplant candidacy or mesenteric extension','Those features can increase the benefit of recanalization.')],
 'Name the guideline because vascular treatment is risk- and context-dependent', '**Recent limited thrombosis without ischemia can enter an imaging-surveillance pathway.**', ['Potential transplant status and extension are important modifiers.','New progression or symptoms prompts reassessment.'], '**Observation is an active plan, not abandonment.**', ['Document timing, extent and follow-up.','Address portal-hypertension complications and the underlying liver disease.'], [['Limited recent stable PVT','Observation may be appropriate'],['Repeat imaging','About every 3 months'],['Progression/major risk modifier','Reconsider anticoagulation']], [PV], 'clinical_scenario')
q('A cirrhotic patient has recent 70% main portal vein thrombosis extending into the superior mesenteric vein. Which treatment direction is generally appropriate?', 'Assess promptly for anticoagulation and for intestinal ischemia, with transplant implications considered',[
 ('Treat identically to a tiny stable intrahepatic branch clot without review','Extent and major-vessel involvement change the balance.'),('Assume elevated INR provides adequate endogenous anticoagulation','Cirrhosis does not protect against thrombosis.'),('Wait for complete chronic occlusion before discussing treatment','Earlier recanalization can be more achievable.')],
 'Greater occlusion and extension increase the potential benefit of treatment', '**Recent major-vein or more-than-50% occlusive PVT is a common anticoagulation indication context.**', ['Assess bleeding risks and variceal prevention without unnecessary delay.','Transplant candidates may have an additional anatomical benefit from recanalization.'], '**Monitor both safety and clot response.**', ['Agent choice depends on liver/renal function and other factors.','Repeat imaging guides the next decision.'], [['Recent >50% main-vein clot','Anticoagulation consideration'],['Mesenteric extension','Ischemia relevance'],['Transplant','Preserve portal anatomy']], [VA,PV], 'clinical_scenario')
q('Under the AGA update, what is the usual anticoagulation approach to chronic complete PVT with established cavernous transformation in cirrhosis, without a separate indication?', 'Routine anticoagulation solely to recanalize the old complete occlusion is not advised',[
 ('It always guarantees full recanalization within days','Organized chronic obstruction is different from recent clot.'),('It removes all need to manage portal-hypertension complications','Complication care remains important.'),('No expert vascular intervention can ever be considered for a transplant problem','Selected portal recanalization/TIPS strategies may still be relevant.')],
 'Chronic organized occlusion is a different therapeutic target', '**The AGA recommendation distinguishes it from recent potentially recanalizable PVT.**', ['A separate thrombophilic or thrombotic indication may change anticoagulation decisions.','Other guidelines and transplant contexts can require individualized expert review.'], '**Focus on the actual residual problem.**', ['Treat varices, portal biliopathy or other complications when present.','Assess expert reconstruction if transplant feasibility is affected.'], [['Recent clot','Recanalization goal plausible'],['Chronic complete cavernoma','No routine anticoagulation solely for old-clot reversal'],['Selected transplant issue','Expert vascular strategy']], [PV])
q('What does portal cavernous transformation represent?', 'A network of venous collaterals developing around an obstructed portal vein',[
 ('A cavernous hemangioma replacing every hepatic vein','This confuses a tumor name with portal collaterals.'),('Proof that the portal vein is normally patent','It indicates altered portal-flow anatomy.'),('An obligatory sign of malignant invasion','Chronic bland thrombosis can produce it.')],
 'Collateralization is an adaptation to chronic obstruction', '**Small vessels bypass the obstructed portal segment.**', ['The anatomy may contribute to portal hypertension and biliary compression.','Its presence helps characterize chronicity but should be interpreted with prior imaging.'], '**Assess complications rather than the image label alone.**', ['Varices and portal biliopathy can become clinically important.','Intervention depends on symptoms and the broader vascular plan.'], [['Cavernoma','Collateral venous network'],['Cause','Chronic portal obstruction'],['Complications','Portal hypertension/biliopathy']], [VA,PV])
q('A patient with chronic portal cavernoma develops cholestasis and biliary irregularity. Which mechanism is possible?', 'Portal cavernoma-associated cholangiopathy from collateral compression and ischemic duct injury',[
 ('Every duct irregularity in this context proves primary PSC','A vascular cause must be considered.'),('Gilbert syndrome','This does not explain cholestatic enzymes and duct distortion.'),('A simple isolated unconjugated-bilirubin transport defect','That does not cause the stated structural pattern.')],
 'Portal and biliary anatomy can interact', '**Peribiliary collaterals can compress or distort ducts.**', ['Ischemic changes can also contribute.','Not every radiographic change is symptomatic or needs intervention.'], '**Treat clinically important obstruction or cholangitis through an expert pathway.**', ['Endoscopic intervention can carry bleeding risk from collaterals.','Portal decompression or recanalization may be part of selected definitive planning.'], [['Portal cavernoma','Collateral anatomy'],['Duct effects','Compression/ischemia'],['Treatment','Symptoms and anatomy dependent']], [VA], 'clinical_scenario')
q('A patient has large varices and splenomegaly, relatively preserved synthesis and liver stiffness lower than expected for cirrhosis. What alternative deserves assessment?', 'Portosinusoidal vascular disorder/noncirrhotic portal fibrosis',[
 ('Cirrhosis is excluded or confirmed solely by the stiffness number','Stiffness must be interpreted with the clinical and pathological context.'),('Gilbert syndrome as a complete explanation','This cannot explain portal hypertension.'),('No liver-related disease because synthesis is preserved','Presinusoidal vascular disease can preserve synthesis despite portal complications.')],
 'Portal hypertension does not always mean cirrhosis', '**PSVD can cause clinically important portal complications with a different architectural lesion.**', ['Histology may show obliterative portal venopathy or nodular regenerative changes.','The diagnosis requires an adequate biopsy and exclusion/assessment of relevant alternatives.'], '**Do not apply cirrhosis-specific noninvasive rules uncritically.**', ['Investigate associated systemic, immune, drug and prothrombotic conditions.','Manage variceal risk according to the portal-hypertension phenotype.'], [['Portal signs disproportionate to stiffness','Consider PSVD'],['Biopsy','Adequacy important'],['Preserved function','Does not eliminate portal risk']], [VA,BV], 'clinical_scenario')
q('Why can HVPG be normal or only mildly elevated in severe presinusoidal portal hypertension?', 'The wedged hepatic venous measurement does not fully capture resistance located before the sinusoids',[
 ('A normal HVPG excludes every form of portal hypertension','That is true only within a more limited anatomical interpretation.'),('Presinusoidal disease can never cause varices','It can cause major portal complications.'),('HVPG is simply the systolic blood pressure','It measures a hepatic venous pressure difference.')],
 'Pressure measurement depends on where the resistance lies', '**HVPG is most informative in sinusoidal portal hypertension such as typical cirrhosis.**', ['Prehepatic or presinusoidal obstruction may be missed by that gradient.','Clinical varices, collaterals and vascular imaging remain important.'], '**Resolve a discordance rather than dismissing the portal signs.**', ['Assess portal and hepatic venous anatomy.','Consider vascular disorders and an adequate tissue assessment when appropriate.'], [['Sinusoidal disease','HVPG usually reflects pressure burden'],['Presinusoidal disease','Gradient may underestimate'],['Varices with low HVPG','Investigate anatomy']], [VA,BV])
q('After hematopoietic stem-cell transplantation, a patient develops painful hepatomegaly, rapid weight gain, ascites and rising bilirubin. Which vascular syndrome is concerning?', 'Hepatic sinusoidal obstruction syndrome',[
 ('Uncomplicated Gilbert syndrome','This does not explain fluid retention and painful hepatomegaly.'),('Isolated extrahepatic choledocholithiasis as the only possibility','The transplant timing and congestion pattern suggest a different syndrome.'),('Benign isolated transaminase adaptation','The multisystem clinical pattern is more serious.')],
 'Conditioning-related endothelial injury can obstruct sinusoidal outflow', '**SOS, formerly veno-occlusive disease, is a recognized post-HSCT complication.**', ['Diagnostic criteria depend on timing and clinical setting.','Assess renal, pulmonary and other organ dysfunction.'], '**Escalate early to the transplant team.**', ['Supportive fluid management and disease-specific therapy depend on severity.','Do not wait for a classic complete triad if the evolving syndrome is concerning.'], [['Setting','HSCT/conditioning exposure'],['Clues','Weight gain, hepatomegaly, ascites, bilirubin'],['Severity','Multiorgan dysfunction']], [VA], 'clinical_scenario')
q('Which drug has a US indication for post-HSCT hepatic SOS with renal or pulmonary dysfunction?', 'Defibrotide',[
 ('Resmetirom','This treats a selected MASH setting, not this transplant vascular syndrome.'),('Bulevirtide','This targets HDV entry.'),('Elafibranor','This is a PBC-related therapy.')],
 'Match the treatment to the exact approved syndrome', '**Defibrotide is used for severe post-HSCT SOS in the specified organ-dysfunction setting.**', ['Bleeding risk and interacting anticoagulant/fibrinolytic therapy require careful review.','Supportive and transplant-team care remain essential.'], '**Do not apply the indication to every cause of post-transplant jaundice.**', ['Infection, drug injury and obstruction remain alternatives.','The diagnosis and severity assessment should be made promptly.'], [['Defibrotide','Specified severe SOS setting'],['Safety','Bleeding review'],['Differential','Other causes of post-HSCT liver injury']], [ref('US Defibrotide Prescribing Information','https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=2c3db989-d7ad-41ed-9ebf-698dcf6c24ec')])
q('A congested patient has elevated JVP, pulsatile hepatomegaly and abnormal liver tests. Which test helps distinguish cardiac congestion from primary hepatic-vein thrombosis?', 'Echocardiographic assessment combined with appropriate hepatic/IVC Doppler imaging',[
 ('AMA alone','It does not define cardiac function or venous anatomy.'),('Serum ceruloplasmin alone','This addresses a different differential.'),('A single ALT measurement as definitive localization','ALT cannot locate the venous pressure source.')],
 'Trace the outflow obstruction back to its source', '**Right-heart and pericardial disease can cause hepatic congestion without primary Budd–Chiari.**', ['Assess valve disease, ventricular function and pericardial physiology.','Doppler patterns and venous patency add anatomical information.'], '**Treat the upstream hemodynamic disease.**', ['A hepatic label should not delay cardiac management.','Chronic congestion and other liver disease can coexist.'], [['Cardiac congestion','High downstream venous pressure'],['Budd–Chiari','Primary hepatic outflow obstruction'],['Assessment','Heart plus venous imaging']], [VA], 'clinical_scenario')

